async (page) => {
  const br = page.context().browser();
  const ctx = await br.newContext({viewport:{width:1920,height:1080},locale:'en-US'});
  const pc = await ctx.newPage();
  await pc.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await pc.waitForTimeout(8000);
  const probe = async () => pc.evaluate(() => {
    const vis = e => { const r = e.getBoundingClientRect(); return r.width > 40 && r.height > 20 && r.y > 60; };
    const pop = Array.from(document.querySelectorAll('[class*=popup],[class*=dropdown],[class*=menu],[class*=select],[class*=option]')).filter(vis).map(e => String(e.className).slice(0,70) + ' :: ' + (e.innerText||'').trim().slice(0,70).replace(/\n+/g,' / '));
    return {popups: pop.slice(0, 10), cinematic: document.querySelectorAll('.cinematic-popup').length};
  });
  const res = {before: await probe()};
  const btn = pc.locator('button.cinematic-model').first();
  const box = await btn.boundingBox();
  res.btnBox = box;
  // 策略 A：先聚焦输入框，坐标点击模型按钮
  await pc.getByRole('textbox').first().click({timeout: 8000}).catch(()=>{});
  await pc.waitForTimeout(500);
  if (box) { await pc.mouse.click(box.x + box.width / 2, box.y + box.height / 2); }
  await pc.waitForTimeout(2500);
  res.afterCoordinateClick = await probe();
  await pc.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/pc_model_coord_click.png'});
  // 策略 B：Vue dispatchEvent
  await btn.evaluate(e => e.dispatchEvent(new MouseEvent('click', {bubbles:true, cancelable:true})));
  await pc.waitForTimeout(2500);
  res.afterDispatch = await probe();
  await pc.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260914/pc_model_dispatch.png'});
  await ctx.close();
  return JSON.stringify(res);
}
